import 'dart:convert';

import 'package:flutter/services.dart' show AssetBundle, rootBundle;
import 'package:shared_preferences/shared_preferences.dart';
import 'package:watch_verse/services/games/higher_lower_logic.dart';

/// Loads the shipped "Higher or Lower" pool (`assets/games/
/// higher_lower_pool.json`, generated by `tool/generate_plot_higher_lower_pools.dart`) and
/// keeps the player's personal best per category on-device. No Firestore:
/// the game is endless and personal, there's nothing to sync.
class HigherLowerService {
  HigherLowerService({AssetBundle? bundle}) : _bundle = bundle ?? rootBundle;
  static final HigherLowerService instance = HigherLowerService();

  static const poolAsset = 'assets/games/higher_lower_pool.json';

  final AssetBundle _bundle;
  Map<HigherLowerCategory, List<HigherLowerItem>>? _pool;

  /// Parsed pool; cached after the first successful load. Errors propagate
  /// so the screen can offer a retry.
  Future<Map<HigherLowerCategory, List<HigherLowerItem>>> pool() async {
    final cached = _pool;
    if (cached != null) return cached;
    final raw = await _bundle.loadString(poolAsset);
    final parsed =
        parseHigherLowerPool(jsonDecode(raw) as Map<String, dynamic>);
    _pool = parsed;
    return parsed;
  }

  Future<Map<HigherLowerCategory, int>> bestScores() async {
    final prefs = await SharedPreferences.getInstance();
    return {
      for (final c in HigherLowerCategory.values)
        c: prefs.getInt(higherLowerBestKey(c)) ?? 0,
    };
  }

  /// Stores [score] if it beats the saved best; returns the (new) best.
  Future<int> submitScore(HigherLowerCategory c, int score) async {
    final prefs = await SharedPreferences.getInstance();
    final best = prefs.getInt(higherLowerBestKey(c)) ?? 0;
    if (score <= best) return best;
    await prefs.setInt(higherLowerBestKey(c), score);
    return score;
  }
}
